const express = require('express');
const { Pool } = require('pg');
const app = express();

// Postgres pool — honours the standard DATABASE_URL env var so that
// the readiness probe works in every environment without code changes.
const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
});

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Kubernetes readiness probe
// Returns 200 {"db":"ok"} when Postgres is reachable, 503 otherwise.
app.get('/healthz', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.status(200).json({ db: 'ok' });
  } catch (err) {
    console.error('Health check failed:', err.message);
    res.status(503).json({ db: 'unavailable' });
  }
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

