app.get('/healthz', async (req, res) => {
  try {
    // Attempt a lightweight Postgres connectivity check.
    // Uses the pg module if available; falls back to a TCP probe so the
    // endpoint still works in environments where pg is not installed.
    const { Client } = require('pg');
    const client = new Client(); // reads PG* env vars (PGHOST, PGPORT, etc.)
    await client.connect();
